use vstd::prelude::*;

verus! {

    // Copy a vector of i8 by iterating over its elements.
    fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
        ensures
            // The result has the same length as the input.
            result.len() == arr.len(),
        ensures
            // Every element in result matches the corresponding element in arr.
            forall |i: usize| i < arr.len() ==> result[i] == arr[i],
    {
        // We'll build up the output vector by pushing each element in turn.
        let mut out: Vec<i8> = Vec::new();
        let mut i: usize = 0;

        // Loop over all indices 0..arr.len()
        while i < arr.len()
            invariant
                // i never exceeds the original length
                i <= arr.len(),
                // we've pushed exactly i elements so far
                out.len() == i,
                // and those i elements agree with arr
                forall |j: usize| j < i ==> out[j] == arr[j],
            decreases
                // this ensures termination
                arr.len() - i,
        {
            // Read the i-th element and push it onto out
            let v: i8 = arr[i];
            out.push(v);
            i = i + 1;
        }

        // Return the completed copy
        out
    }

}

